import{_ as t,o,c as a,a2 as i}from"./chunks/framework.u0XqMXcb.js";const m=JSON.parse('{"title":"PII Redactor","description":"","frontmatter":{"title":"PII Redactor"},"headers":[],"relativePath":"docs/tools/pii-redactor.md","filePath":"docs/tools/pii-redactor.md","lastUpdated":1790281380000}'),r={name:"docs/tools/pii-redactor.md"};function s(n,e,d,l,c,p){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="pii-redactor" tabindex="-1">PII Redactor <a class="header-anchor" href="#pii-redactor" aria-label="Permalink to &quot;PII Redactor&quot;">​</a></h1><p>The PII Redactor strips personal information out of a document — useful when you want to share or save a sample statement (for example, to help build support for a new format) without exposing anything private.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ol><li>Drag and drop a PDF, CSV, or spreadsheet file onto the tool.</li><li>Click <strong>Auto-detect</strong> to find likely personal information — names, account numbers, and similar details.</li><li>Review and edit the list of detected items — add anything that was missed, or remove a false positive.</li><li>Click <strong>Redact</strong>, then preview the result before saving it.</li></ol><p>An option to skip images is available if a document&#39;s redaction doesn&#39;t need to cover embedded images. Redaction settings can be saved and reused across documents, so you don&#39;t have to redo the same review every time.</p><p>Just want to see what&#39;s in a document without producing a cleaned-up file? Use the <a href="/OrbySystems-Finance/docs/tools/pii-detector">PII Detector</a> instead.</p>',6)])])}const u=t(r,[["render",s]]);export{m as __pageData,u as default};
